{"command": "cd /workspace/vllm-project/vllm && cat > /tmp/extract.py << 'EOF'
import re

with open('/tmp/sgmv_expand.py', 'r') as f:
    lines = f.readlines()

def extract_function(start_line):
    # find line where def appears
    i = 0
    while i < len(lines) and not lines[i].strip().startswith(start_line):
        i += 1
    if i == len(lines):
        return ''
    start = i
    # find next line that starts with def or @ (excluding whitespace) at same indent level
    base_indent = len(lines[start]) - len(lines[start].lstrip())
    j = start + 1
    while j < len(lines):
        stripped = lines[j].strip()
        if stripped and not stripped.startswith('#'):
            indent = len(lines[j]) - len(lines[j].lstrip())
            if indent == base_indent and (stripped.startswith('def ') or stripped.startswith('@')):
                break
        j += 1
    return ''.join(lines[start:j])

kernel = extract_function('def _sgmv_expand_kernel')
wrapper = extract_function('def _sgmv_expand')

with open('/tmp/sgmv_shrink.py', 'r') as f:
    lines = f.readlines()
kernel2 = extract_function('def _sgmv_shrink_kernel')
wrapper2 = extract_function('def _sgmv_shrink')

import json
result = {
    "vllm/lora/ops/sgmv_expand.py": {
        "_sgmv_expand_kernel": kernel,
        "_sgmv_expand": wrapper
    },
    "vllm/lora/ops/sgmv_shrink.py": {
        "_sgmv_shrink_kernel": kernel2,
        "_sgmv_shrink": wrapper2
    }
}
with open('/prediction.json', 'w') as f:
    json.dump(result, f, indent=2)
EOF"}

